{
    $this->storeCurrentCell();

    $columnIndex = Coordinate::columnIndexFromString($column);
    foreach ($this->index as $coordinate) {
        if ($coordinate % self::MAX_COLUMN_ID === $columnIndex) {
            $row = (int) floor($coordinate / self::MAX_COLUMN_ID) + 1;
